package com.order.order_service.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="order_id",nullable=false) private Long orderId; @Column(name="menu_item_id",nullable=false) private Long menuItemId; @Column(name="restaurant_id",nullable=false) private Long restaurantId; @Column(name="item_name",nullable=false,length=160) private String itemName; @Column(name="unit_price",nullable=false,precision=12,scale=2) private BigDecimal unitPrice; @Column(nullable=false) private Integer quantity; protected OrderItem(){} public OrderItem(Long o,Long m,Long r,String n,BigDecimal p,Integer q){orderId=o;menuItemId=m;restaurantId=r;itemName=n;unitPrice=p;quantity=q;} public Long getId(){return id;} public Long getOrderId(){return orderId;} public Long getMenuItemId(){return menuItemId;} public Long getRestaurantId(){return restaurantId;} public String getItemName(){return itemName;} public BigDecimal getUnitPrice(){return unitPrice;} public Integer getQuantity(){return quantity;} }
